"""
rebuild_book.py — Complete Publishing Pipeline for "No Blue Sky: Built from Dust"
Book 1 of the No Blue Sky Series.

Phases:
  1. Read & analyze manuscript
  2. Build print-ready HTML with proper 6"x9" CSS and TOC table
  3. Generate review PDF → extract page numbers → hardcode into HTML
  4. Generate final PDF
  5. Generate EPUB 3

Usage:
  python3 rebuild_book.py
"""

import os, re, sys, subprocess, tempfile, io, zipfile
from datetime import datetime, timezone
from xml.sax.saxutils import escape as xmlescape

# ── Paths ──────────────────────────────────────────────────────────────────
BOOK_DIR = "/home/bob/books/No_Blue_Sky_Series/Book_I_Built_from_Dust"
MANUSCRIPT = os.path.join(BOOK_DIR, "manuscript.md")
PDF_OUT = os.path.join(BOOK_DIR, "No_Blue_Sky_1_Built_from_Dust_Print.pdf")
REVIEW_HTML = os.path.join(BOOK_DIR, ".review_build.html")
REVIEW_PDF = os.path.join(BOOK_DIR, ".review_build.pdf")
EPUB_OUT = os.path.join(BOOK_DIR, "No_Blue_Sky_1_Built_from_Dust.epub")
KINDLE_EPUB_OUT = os.path.join(BOOK_DIR, "Kindle", "No_Blue_Sky_1_Built_from_Dust.epub")
COVER_JPG = os.path.join(BOOK_DIR, "generated_images", "Kindle_Cover.jpg")

# ── Book Metadata ──────────────────────────────────────────────────────────
TITLE = "No Blue Sky: Built from Dust"
SUBTITLE = "The First Martian Generation"
SERIES = "No Blue Sky Series • Book I"
AUTHOR = "Bob N."
PUBLISHER = "Self-Published"
LANG = "en"
DESCRIPTION = (
    "A novel of Mars colonization, survival, and the birth of a civilization. "
    "Three ships land on an ochre plain. Thirty souls. Nine days before a dust storm hits. "
    "This is not a return mission — this is a beginning."
)


# ══════════════════════════════════════════════════════════════════════════
# PHASE 1: Read & Analyze Manuscript
# ══════════════════════════════════════════════════════════════════════════

def slug(name):
    """Filesystem-safe slug from a heading string."""
    s = name.lower().replace(" ", "-").replace(":", "").replace("—", "-")
    s = re.sub(r"[^a-z0-9.-]", "", s)[:60]
    return s


def parse_manuscript(text):
    """
    Parse the manuscript into a structured list of entries.

    Returns:
      entries: list of dicts with keys:
        - type: 'front', 'chapter', 'part', 'interstitial', 'back'
        - heading: display heading text
        - level: 'h1' or 'h2'
        - body: list of body paragraph strings (raw markdown lines)
        - slug: filename-safe slug
    """
    lines = text.split("\n")
    entries = []

    # Front matter: everything before the first ## Chapter or # PART
    i = 0
    front_lines = []
    while i < len(lines):
        stripped = lines[i].strip()
        if re.match(r"^## Chapter \d", stripped) or re.match(r"^# PART", stripped):
            break
        front_lines.append(lines[i])
        i += 1
    # Store front matter as first entry (title page + subtitle info)
    entries.append({
        "type": "front",
        "heading": "Front Matter",
        "level": "h1",
        "body": front_lines,
        "slug": "front-matter"
    })

    # Now parse the body chapters
    chapter_pattern = re.compile(r"^## (Chapter \d+[—–-]?.+)$")
    part_pattern = re.compile(r"^# (PART .+)$")
    interstitial_pattern = re.compile(r"^## (The Years Between|Interlude.*)$")
    # Also catch any ## that's not a chapter (like ## The Years Between)
    other_h2_pattern = re.compile(r"^## (.+)$")

    current_entry = None
    current_body = []

    for i in range(i, len(lines)):
        stripped = lines[i].strip()
        line = lines[i]

        # Check for part headings (# PART ...)
        m = part_pattern.match(stripped)
        if m:
            if current_entry is not None:
                current_entry["body"] = current_body
                entries.append(current_entry)
            current_entry = {
                "type": "part",
                "heading": m.group(1),
                "level": "h1",
                "body": [],
                "slug": slug(m.group(1))
            }
            current_body = []
            continue

        # Check for chapter headings (## Chapter N ...)
        m = chapter_pattern.match(stripped)
        if m:
            if current_entry is not None:
                current_entry["body"] = current_body
                entries.append(current_entry)
            current_entry = {
                "type": "chapter",
                "heading": m.group(1),
                "level": "h2",
                "body": [],
                "slug": slug(m.group(1))
            }
            current_body = []
            continue

        # Check for interstitial headings (## The Years Between etc.)
        m = other_h2_pattern.match(stripped)
        if m and current_entry is not None:
            # Could be an interstitial heading
            heading_text = m.group(1)
            if "Chapter" not in heading_text:
                if current_entry is not None:
                    current_entry["body"] = current_body
                    entries.append(current_entry)
                current_entry = {
                    "type": "interstitial",
                    "heading": heading_text,
                    "level": "h2",
                    "body": [],
                    "slug": slug(heading_text)
                }
                current_body = []
                continue

        if current_entry is not None:
            current_body.append(line)

    # Flush last entry
    if current_entry is not None:
        current_entry["body"] = current_body
        entries.append(current_entry)

    return entries


def count_words(text):
    """Count words in a text string."""
    return len(text.split())


def md_to_html_body(body_lines, indent=0):
    """
    Convert parsed body lines to HTML paragraphs.
    Handles epigraphs (italic lines starting/ending with *),
    horizontal rules (---), blockquotes (>), scene breaks, etc.
    """
    html_parts = []
    for line in body_lines:
        stripped = line.strip()
        if not stripped:
            continue

        # Horizontal rule
        if stripped.startswith("---") and len(stripped) <= 4:
            html_parts.append("<hr/>")
            continue

        # Epigraph / italic section lines (single * on each side, not bold)
        if re.match(r"^\*[^*]+\*$", stripped) and "**" not in stripped:
            inner = stripped.strip("*").strip()
            html_parts.append(f'<p class="epigraph">{xmlescape(inner)}</p>')
            continue

        # Italic lines with content (scene breaks)
        if stripped.startswith("*") and stripped.endswith("*") and "**" not in stripped:
            inner = stripped.strip("*").strip()
            html_parts.append(f'<p class="scene-break">{xmlescape(inner)}</p>')
            continue

        # Blockquotes
        if stripped.startswith(">"):
            quote = stripped[1:].strip()
            html_parts.append(f"<blockquote><p>{xmlescape(quote)}</p></blockquote>")
            continue

        # Regular paragraph - handle inline formatting
        text = stripped
        # Bold: **text**
        text = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", text)
        # Italic: *text* (not already bold)
        text = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", r"<em>\1</em>", text)

        html_parts.append(f"<p>{text}</p>")

    return "\n".join(html_parts)


