def build_full_html(entries, toc_page_numbers=None):
    """
    Build the complete HTML document with print CSS.

    Args:
      entries: parsed manuscript entries
      toc_page_numbers: optional dict mapping slug -> page_number (for final pass)

    Returns:
      Full HTML string
    """
    parts = []

    # ── Title Page ──
    parts.append(f"""
<div class="title-page">
  <p class="series-name">{xmlescape(SERIES)}</p>
  <h1 class="book-title">{xmlescape(TITLE)}</h1>
  <p class="subtitle">{xmlescape(SUBTITLE)}</p>
  <p class="author">by {xmlescape(AUTHOR)}</p>
</div>
""")

    # ── Copyright Page ──
    parts.append(f"""
<div class="copyright-page">
  <p><strong>Copyright &copy; 2026 by {xmlescape(AUTHOR)}</strong></p>
  <p>All rights reserved. No part of this publication may be reproduced, distributed, or transmitted in any form or by any means, including photocopying, recording, or other electronic or mechanical methods, without the prior written permission of the publisher, except in the case of brief quotations embodied in critical reviews and certain other noncommercial uses permitted by copyright law.</p>
  <p>This is a work of fiction. Names, characters, places, and incidents either are the product of the author&rsquo;s imagination or are used fictitiously. Any resemblance to actual persons, living or dead, events, or locales is entirely coincidental.</p>
  <p class="publisher-name">{xmlescape(PUBLISHER)}</p>
</div>
""")

    # ── TOC Page ──
    parts.append(build_toc_html(entries, toc_page_numbers))

    # ── Content Chapters ──
    for entry in entries:
        if entry["type"] == "front":
            continue  # Already rendered as title page

        heading_tag = entry["level"]
        heading_text = entry["heading"]
        body_html = md_to_html_body(entry["body"])

        # Part heading
        if entry["type"] == "part":
            parts.append(f"<{heading_tag}>{xmlescape(heading_text)}</{heading_tag}><hr/>\n")
        elif entry["type"] == "interstitial":
            parts.append(f"<{heading_tag}>{xmlescape(heading_text)}</{heading_tag}>\n")
            parts.append(body_html)
        elif entry["type"] == "chapter":
            parts.append(f"<{heading_tag}>{xmlescape(heading_text)}</{heading_tag}>\n")
            parts.append(body_html)

    # ── About the Author (Back Matter) ──
    parts.append(f"""
<div class="about-author">
  <h2>About the Author</h2>
  <p>{xmlescape(AUTHOR)} is a writer of speculative fiction exploring humanity&rsquo;s future beyond Earth. With a background in systems engineering and a lifelong fascination with space exploration, their work focuses on the intersection of technology, society, and the human spirit. <em>{xmlescape(TITLE)}</em> is the first book in the No Blue Sky series, a multi-generational saga of Mars colonization and the birth of a new civilization.</p>
</div>
""")

    # ── Also By / Series Page ──
    parts.append(f"""
<div class="series-page">
  <h2>Also in the No Blue Sky Series</h2>
  <p><strong>Book I:</strong> {xmlescape(TITLE)}</p>
  <p><em>Coming Soon</em></p>
  <p style="margin-top:2em;font-size:9pt;color:#666;">Stay tuned for Book II: <em>No Blue Sky: Breaking Ground</em></p>
</div>
""")

    body_html = "\n".join(parts)
    css = build_print_css()

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<title>{xmlescape(TITLE)}</title>
<style>{css}</style>
</head>
<body>
{body_html}
</body>
</html>"""


def build_toc_html(entries, page_numbers=None):
    """
    Build TOC as an HTML table with chapter titles and page numbers.

    Args:
      entries: parsed manuscript entries
      page_numbers: dict mapping slug -> actual page number (or None for placeholders)

    Returns:
      HTML string for the TOC page
    """
    toc_rows = []
    for entry in entries:
        if entry["type"] == "front":
            continue

        pnum = ""
        if page_numbers and entry["slug"] in page_numbers and entry["type"] in ("chapter", "interstitial"):
            pnum = str(page_numbers[entry["slug"]])
        elif not page_numbers and entry["type"] in ("chapter", "interstitial"):
            pnum = "•••"  # Placeholder

        row_class = f'toc-{entry["type"]}'

        if entry["type"] == "part":
            toc_rows.append(
                f'<tr class="{row_class}">'
                f'<td colspan="2">{xmlescape(entry["heading"])}</td>'
                f'</tr>'
            )
        elif entry["type"] == "interstitial":
            toc_rows.append(
                f'<tr class="{row_class}">'
                f'<td class="toc-chapter">{xmlescape(entry["heading"])}</td>'
                f'<td class="toc-page-num">{pnum}</td>'
                f'</tr>'
            )
        elif entry["type"] == "chapter":
            toc_rows.append(
                f'<tr>'
                f'<td class="toc-chapter">{xmlescape(entry["heading"])}</td>'
                f'<td class="toc-page-num">{pnum}</td>'
                f'</tr>'
            )

    return f"""
<div class="toc-page">
  <h1>Contents</h1>
  <table class="toc-table">
  {chr(10).join(toc_rows)}
  </table>
</div>
"""


