# Page Number Extraction from PDF
# ══════════════════════════════════════════════════════════════════════════

def extract_page_numbers_from_pdf(pdf_path, entries):
    """
    Extract actual page numbers for each chapter by searching for
    chapter headings in the PDF text.

    Uses pdftotext to get page-by-page text, then matches chapter headings.

    Returns:
      dict mapping entry slug -> actual page number (1-indexed)
    """
    if not os.path.exists(pdf_path):
        print(f"  WARNING: PDF not found at {pdf_path}")
        return {}

    # Get page count
    result = subprocess.run(
        ["pdfinfo", pdf_path],
        capture_output=True, text=True
    )
    page_count = 0
    for line in result.stdout.split("\n"):
        if "Pages" in line:
            page_count = int(line.split(":")[1].strip())
            break

    if page_count == 0:
        print("  WARNING: Could not determine PDF page count")
        return {}

    print(f"  PDF has {page_count} pages. Extracting chapter locations...")

    page_numbers = {}
    for entry in entries:
        if entry["type"] not in ("chapter", "interstitial"):
            continue

        # Search for the heading text in PDF pages
        heading = entry["heading"]
        # Use pdftotext with layout to find the page
        found_page = None

        # Binary search or linear scan pages
        for pg in range(1, page_count + 1):
            result = subprocess.run(
                ["pdftotext", "-f", str(pg), "-l", str(pg), pdf_path, "-"],
                capture_output=True, text=True
            )
            page_text = result.stdout
            # Check for the heading (the chapter title appears near the top of the page)
            if heading in page_text:
                found_page = pg
                break

        if found_page:
            page_numbers[entry["slug"]] = found_page
            print(f"    {heading} -> page {found_page}")
        else:
            print(f"    WARNING: Could not find '{heading}' in PDF")
            page_numbers[entry["slug"]] = 0

    return page_numbers


