             border-left: 2px solid #ccc; color: #444; }
p.epigraph { text-align: center; font-style: italic; color: #555;
             text-indent: 0; margin: 0.5em 1.5em; }
p.scene-break { text-align: center; font-style: italic; text-indent: 0;
                margin: 0.4em 0; color: #666; }
"""

    # ── OPF ──
    manifest = []
    spine = []

    def add(fn, mt, props="", in_spine=True):
        manifest.append(f'    <item id="{fn}" href="{fn}" media-type="{mt}"' +
                        (f' {props}' if props else "") + "/>")
        if in_spine:
            spine.append(f'    <itemref idref="{fn}"/>')

    add("nav.xhtml", "application/xhtml+xml", 'properties="nav"', in_spine=False)
    add("toc.ncx", "application/x-dtbncx+xml", in_spine=False)
    add("styles/epub.css", "text/css", in_spine=False)
    add("cover.jpg", "image/jpeg", 'properties="cover-image"', in_spine=False)

    for fn, _, _ in all_chapters:
        add(fn, "application/xhtml+xml")

    opf = f"""<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="book-id">
<metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
<dc:identifier id="book-id">{book_id}</dc:identifier>
<dc:title>{xmlescape(TITLE)}</dc:title>
<dc:creator>{xmlescape(AUTHOR)}</dc:creator>
<dc:language>{LANG}</dc:language>
<dc:publisher>{xmlescape(PUBLISHER)}</dc:publisher>
<dc:date>{date_str}</dc:date>
<dc:description>{xmlescape(DESCRIPTION)}</dc:description>
<meta property="dcterms:modified">{ts}</meta>
</metadata>
<manifest>
{chr(10).join(manifest)}
</manifest>
<spine page-progression-direction="ltr">
{chr(10).join(spine)}
</spine>
<guide>
<reference type="cover" title="Cover" href="cover.xhtml"/>
<reference type="toc" title="Table of Contents" href="nav.xhtml"/>
<reference type="text" title="Start" href="{all_chapters[3][0]}"/>
</guide>
</package>"""

    # ── NCX (EPUB 2 fallback) ──
    ncx_pts = []
    for i, (fn, htext, _) in enumerate(all_chapters[1:], 1):
        ncx_pts.append(
            f'    <navPoint id="{fn}" playOrder="{i}">'
            f'<navLabel><text>{xmlescape(htext)}</text></navLabel>'
            f'<content src="{fn}"/>'
            f"</navPoint>"
        )
    ncx = f"""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE ncx PUBLIC "-//NISO//DTD ncx 2005-1//EN"
 "http://www.daisy.org/z3986/2005/ncx-2005-1.dtd">
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
<head><meta name="dtb:uid" content="{book_id}"/><meta name="dtb:depth" content="1"/></head>
<docTitle><text>{xmlescape(TITLE)}</text></docTitle>
<navMap>{chr(10).join(ncx_pts)}</navMap>
</ncx>"""

    # ── Assemble EPUB ──
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        # mimetype must be first and uncompressed
        z.writestr("mimetype", "application/epub+xml", compress_type=zipfile.ZIP_STORED)

        # META-INF
        z.writestr("META-INF/container.xml",
                    '<?xml version="1.0" encoding="UTF-8"?>\n'
                    '<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">\n'
                    '<rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>\n'
                    '</rootfiles></container>')

        # OEBPS files
        z.writestr("OEBPS/content.opf", opf.encode("utf-8"))
        z.writestr("OEBPS/nav.xhtml", nav_xhtml.encode("utf-8"))
        z.writestr("OEBPS/toc.ncx", ncx.encode("utf-8"))
        z.writestr("OEBPS/styles/epub.css", epub_css.encode("utf-8"))

        # Cover image
        if os.path.exists(COVER_JPG):
            with open(COVER_JPG, "rb") as f:
                cover_data = f.read()
            z.writestr("OEBPS/cover.jpg", cover_data)
        else:
            print("  WARNING: Cover image not found at", COVER_JPG)

        # Content files
        for fn, htext, xhtml in all_chapters:
            z.writestr(f"OEBPS/{fn}", xhtml.encode("utf-8"))

    with open(EPUB_OUT, "wb") as f:
        f.write(buf.getvalue())

    sz = os.path.getsize(EPUB_OUT)
    print(f"  ✓ EPUB built: {EPUB_OUT} ({sz:,} bytes)")
    print(f"  Total content files: {len(all_chapters)}")

    # Also write to Kindle directory
    kindle_dir = os.path.dirname(KINDLE_EPUB_OUT)
    if not os.path.exists(kindle_dir):
        os.makedirs(kindle_dir)
    with open(KINDLE_EPUB_OUT, "wb") as f:
        f.write(buf.getvalue())
    print(f"  ✓ Kindle EPUB written: {KINDLE_EPUB_OUT}")

